export default async function handler(req, res) {
    if (req.method !== 'POST') {
        return res.status(405).json({ error: 'Method Not Allowed' });
    }

    try {
        const { lines } = req.body;

        if (!lines || !Array.isArray(lines) || lines.length !== 6) {
            return res.status(400).json({ error: 'Invalid input' });
        }

        const hexagram = HEXAGRAMS.find(h =>
            h.pattern.every((line, index) => line === lines[index])
        );

        if (!hexagram) {
            return res.status(404).json({ error: 'Hexagram not found' });
        }

        return res.status(200).json({
            hexagramName: hexagram.name,
            originalText: hexagram.level,
            generalMeaning: hexagram.generalMeaning,
            career: hexagram.career,
            wealth: hexagram.wealth,
            love: hexagram.love,
            family: hexagram.family,
            advice: hexagram.advice,
            symbolMeaning: hexagram.symbolMeaning
        });

    } catch (error) {
        console.error("Error in API:", error);
        return res.status(500).json({
            error: 'Failed to interpret hexagram',
            details: error instanceof Error ? error.message : String(error)
        });
    }
}
